concept_admission.output:
只输出 JSON。每个输入 leaf_id 恰好出现一次，每个叶节点列出的 event_id 在其 instance_reviews 中恰好出现一次。不要省略单例或只审核部分来源。
{
  "reviews": [
    {
      "leaf_id": "输入叶节点 ID",
      "concept_checks": {
        "within_scope": {"verdict": "pass|fail|uncertain", "reason": "范围依据"},
        "reusable_type": {"verdict": "pass|fail|uncertain", "reason": "类型依据"},
        "definition_clarity": {"verdict": "pass|fail|uncertain", "reason": "定义依据"}
      },
      "instance_reviews": [
        {
          "event_id": "输入事件 ID",
          "evidence_support": {"verdict": "pass|fail|uncertain", "reason": "原文支持或冲突"},
          "instance_of": {"verdict": "pass|fail|uncertain", "reason": "实例归属依据"}
        }
      ],
      "verdict": "pass|fail|uncertain",
      "reason": "整体结论的简短依据"
    }
  ]
}
